USE PPI;
CREATE TABLE producto (idProducto INT IDENTITY(1,1) PRIMARY KEY, nombre VARCHAR(100), descripcion VARCHAR(255), precio DECIMAL(10,2), stock INT, categoria VARCHAR(50), imagen VARCHAR(500));
CREATE TABLE Cliente (IdCliente INT IDENTITY(1,1) PRIMARY KEY, Nombre VARCHAR(100), Apellido VARCHAR(100), Correo VARCHAR(100) UNIQUE, Contrasena VARCHAR(100), Direccion VARCHAR(200), Telefono VARCHAR(20));
CREATE TABLE Empleado (IdEmpleado INT IDENTITY(1,1) PRIMARY KEY, Nombre VARCHAR(100), Apellido VARCHAR(100), Correo VARCHAR(100), Cargo VARCHAR(50), Telefono VARCHAR(20));
CREATE TABLE Carrito (IdCarrito INT IDENTITY(1,1) PRIMARY KEY, IdCliente INT FOREIGN KEY REFERENCES Cliente(IdCliente), FechaCreacion DATETIME DEFAULT GETDATE());
CREATE TABLE DetalleCarrito (IdDetalle INT IDENTITY(1,1) PRIMARY KEY, IdCarrito INT FOREIGN KEY REFERENCES Carrito(IdCarrito), IdProducto INT FOREIGN KEY REFERENCES producto(idProducto), Cantidad INT, PrecioUnitario DECIMAL(10,2));
CREATE TABLE Pedido (IdPedido INT IDENTITY(1,1) PRIMARY KEY, IdCliente INT FOREIGN KEY REFERENCES Cliente(IdCliente), FechaPedido DATETIME DEFAULT GETDATE(), EstadoPedido VARCHAR(50), Total DECIMAL(10,2));
CREATE TABLE Pago (IdPago INT IDENTITY(1,1) PRIMARY KEY, IdPedido INT FOREIGN KEY REFERENCES Pedido(IdPedido), MetodoPago VARCHAR(50), MontoPago DECIMAL(10,2), FechaPago DATETIME DEFAULT GETDATE());
CREATE TABLE PQRS (IdPQRS INT IDENTITY(1,1) PRIMARY KEY, IdCliente INT FOREIGN KEY REFERENCES Cliente(IdCliente), Tipo VARCHAR(50), Descripcion TEXT, FechaCreacion DATETIME DEFAULT GETDATE(), Estado VARCHAR(50));
CREATE TABLE ChatBot (IdChat INT IDENTITY(1,1) PRIMARY KEY, IdCliente INT FOREIGN KEY REFERENCES Cliente(IdCliente), Mensaje TEXT, Respuesta TEXT, FechaChat DATETIME DEFAULT GETDATE());

